        if (Z_TYPE_P(dim) == IS_REFERENCE) {
                dim = Z_REFVAL_P(dim);
@@ -544,7 +572,31 @@ static void ZEND_FASTCALL zend_jit_fetch_dim_is_helper(zend_array *ht, zval *dim
                        offset_key = Z_STR_P(dim);
                        goto str_index;
                case IS_UNDEF:
+                       /* The array may be destroyed while throwing the notice.
+                        * Temporarily increase the refcount to detect this situation. */
+                       if (!(GC_FLAGS(ht) & IS_ARRAY_IMMUTABLE)) {
+                               GC_ADDREF(ht);
+                       }
+                       execute_data = EG(current_execute_data);
+                       opline = EX(opline);
                        zend_jit_undefined_op_helper(EG(current_execute_data)->opline->op2.var);
+                       if (!(GC_FLAGS(ht) & IS_ARRAY_IMMUTABLE) && !GC_DELREF(ht)) {
+                               zend_array_destroy(ht);
+                               if (opline->result_type & (IS_VAR | IS_TMP_VAR)) {
+                                       if (EG(exception)) {
+                                               ZVAL_UNDEF(EX_VAR(opline->result.var));
+                                       } else {
+                                               ZVAL_NULL(EX_VAR(opline->result.var));
+                                       }
+                               }
+                               return;
+                       }
+                       if (EG(exception)) {
+                               if (opline->result_type & (IS_VAR | IS_TMP_VAR)) {
+                                       ZVAL_UNDEF(EX_VAR(opline->result.var));
+                               }
+                               return;
+                       }
                        /* break missing intentionally */
                case IS_NULL:
                        offset_key = ZSTR_EMPTY_ALLOC();
@@ -616,7 +668,19 @@ static int ZEND_FASTCALL zend_jit_fetch_dim_isset_helper(zend_array *ht, zval *d
                        offset_key = Z_STR_P(dim);
                        goto str_index;
                case IS_UNDEF:
+                       /* The array may be destroyed while throwing the notice.
+                        * Temporarily increase the refcount to detect this situation. */
+                       if (!(GC_FLAGS(ht) & IS_ARRAY_IMMUTABLE)) {
+                               GC_ADDREF(ht);
+                       }
                        zend_jit_undefined_op_helper(EG(current_execute_data)->opline->op2.var);
+                       if (!(GC_FLAGS(ht) & IS_ARRAY_IMMUTABLE) && !GC_DELREF(ht)) {
+                               zend_array_destroy(ht);
+                               return 0;
+                       }
+                       if (EG(exception)) {
+                               return 0;
+                       }
                        /* break missing intentionally */
                case IS_NULL:
                        offset_key = ZSTR_EMPTY_ALLOC();
